              <h3 style={{ margin: "0 0 4px", fontSize: "16px" }}>{rec.canonicalName}</h3>
              {rec.parentEntityName && <div style={{ fontSize: "11px", color: "var(--muted)", marginBottom: "4px" }}>Parent: <b>{rec.parentEntityName}</b></div>}
